bg-[#f8fafc]\">\n            <div class=\"max-w-7xl mx-auto space-y-6\">\n                \n                <!-- HEADER DOKUMEN -->\n                <div class=\"grid grid-cols-1 md:grid-cols-2 gap-4\">\n                    <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm p-5 flex justify-between items-start group\">\n                        <div class=\"flex-1\">\n                            <label class=\"block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2\">Tanggal Opname</label>\n                            <input type=\"date\" x-model=\"tanggal\" class=\"w-full text-base font-black text-slate-800 border-none p-0 focus:ring-0 bg-transparent outline-none cursor-pointer\">\n                        </div>\n                        <i class=\"fa-solid fa-calendar-days text-slate-200 group-hover:text-primary transition-colors text-xl\"></i>\n                    </div>\n\n                    <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm p-5 flex justify-between items-start group\">\n                        <div class=\"flex-1\">\n                            <label class=\"block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2\">Catatan / Keterangan</label>\n                            <input type=\"text\" x-model=\"notes\" placeholder=\"Contoh: Audit Stok Harian\" class=\"w-full text-base font-bold text-slate-800 border-none p-0 focus:ring-0 bg-transparent outline-none placeholder:text-slate-300\">\n                        </div>\n                        <i class=\"fa-solid fa-pen-to-square text-slate-200 group-hover:text-primary transition-colors text-xl\"></i>\n                    </div>\n                </div>\n\n                <!-- DAFTAR ITEM DRAFT -->\n                <div class=\"bg-white rounded-[1.5rem] shadow-sm border border-slate-200 overflow-hidden\">\n                    <div class=\"p-5 border-b border-slate-100 bg-slate-50 flex items-center justify-between\">\n                        <div>\n                            <h3 class=\"font-black text-slate-800 flex items-center gap-2\">\n                                <i class=\"fa-solid fa-boxes-stacked text-primary\"></i>\n                                Bahan Baku Stok Opname\n                                <span class=\"bg-primary text-white text-xs px-2.5 py-0.5 rounded-full font-black flex items-center justify-center w-5 h-5\" x-text=\"draftItems.length\"></span>\n                            </h3>\n                        </div>\n                        <button @click=\"openModal()\" class=\"bg-primary hover:bg-blue-700 text-white px-4 py-2 rounded-xl text-xs font-black flex items-center gap-1.5 transition-all shadow-sm\">\n                            <i class=\"fa-solid fa-plus\"></i> + TAMBAH BAHAN\n                        </button>\n                    </div>\n                    <div class=\"overflow-x-auto custom-scrollbar min-h-[300px]\">\n                        <table class=\"w-full text-left border-collapse whitespace-nowrap min-w-[800px]\">\n                            <thead>\n                                <tr class=\"bg-slate-50 border-b border-slate-200 text-[11px] text-slate-500 uppercase tracking-widest\">\n                                    <th class=\"p-4 font-black text-center w-12\">No</th>\n                                    <th class=\"p-4 font-black\">Nama Bahan Baku</th>\n                                    <th class=\"p-4 font-black text-center text-primary\">Qty Aktual</th>\n                                    <th class=\"p-4 font-black text-center\">Qty System</th>\n                                    <th class=\"p-4 font-black text-center\">Qty Selisih</th>\n                                    <th class=\"p-4 font-black text-center w-16\">Aksi</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"text-sm divide-y divide-slate-100\">\n                                <tr x-show=\"draftItems.length === 0\">\n                                    <td colspan=\"6\" class=\"p-16 text-center text-slate-400\">\n                                        <div class=\"w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-3\">\n                                            <i class=\"fa-solid fa-box-open text-2xl text-slate-300\"></i>\n                                        </div>\n                                        <p class=\"font-bold text-sm text-slate-500\">Belum ada bahan baku diopname.</p>\n                                        <p class=\"text-xs text-slate-400 mt-1\">Klik tombol <span class=\"font-black text-primary\">+ TAMBAH BAHAN</span> untuk memasukkan data.</p>\n                                    </td>\n                                </tr>\n                                <template x-for=\"(item, index) in draftItems\" :key=\"item.id\">\n                                    <tr class=\"hover:bg-blue-50/30 transition-colors\">\n                                        <td class=\"p-4 text-center font-black text-slate-400\" x-text=\"index + 1\"></td>\n                                        <td class=\"p-4\">\n                                            <div class=\"font-black text-slate-800 text-sm\" x-text=\"item.name\"></div>\n                                            <div class=\"text-[10px] font-black text-slate-400 mt-0.5 uppercase tracking-widest\" x-text=\"item.category || '-'\"></div>\n                                        </td>\n                                        <td class=\"p-4 text-center\">\n                                            <div class=\"flex items-center justify-center gap-1\">\n                                                <button @click=\"decrementDraftStock(item.id)\" class=\"w-8 h-8 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-600 font-black text-lg flex items-center justify-center transition-all leading-none select-none\">−</button>\n                                                <input type=\"number\" x-model.number=\"item.actual_stock\" class=\"w-16 bg-white border border-slate-300 rounded-lg text-center font-black text-sm text-slate-800 py-1.5 px-1 focus:border-primary focus:ring-1 focus:ring-primary/20 outline-none\" min=\"0\">\n                                                <button @click=\"incrementDraftStock(item.id)\" class=\"w-8 h-8 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-600 font-black text-lg flex items-center justify-center transition-all leading-none select-none\">+</button>\n                                            </div>\n                                        </td>\n                                        <td class=\"p-4 text-center font-black text-slate-500 text-sm\" x-text=\"item.system_stock\"></td>\n                                        <td class=\"p-4 text-center\">\n                                            <template x-if=\"item.actual_stock - item.system_stock < 0\">\n                                                <span class=\"bg-rose-50 text-rose-600 px-2.5 py-1 rounded-lg font-black text-xs flex items-center justify-center gap-1 w-max mx-auto border border-rose-100\">\n                                                    <i class=\"fa-solid fa-arrow-down text-[10px]\"></i> <span x-text=\"item.actual_stock - item.system_stock\"></span>\n                                                </span>\n                                            </template>\n                                            <template x-if=\"item.actual_stock - item.system_stock > 0\">\n                                                <span class=\"bg-emerald-50 text-emerald-600 px-2.5 py-1 rounded-lg font-black text-xs flex items-center justify-center gap-1 w-max mx-auto border border-emerald-100\">\n                                                    <i class=\"fa-solid fa-arrow-up text-[10px]\"></i> +<span x-text=\"item.actual_stock - item.system_stock\"></span>\n                                                </span>\n                                            </template>\n                                            <template x-if=\"item.actual_stock - item.system_stock === 0\">\n                                                <span class=\"bg-slate-100 text-slate-500 px-2.5 py-1 rounded-lg font-black text-[11px] flex items-center justify-center w-max mx-auto tracking-wide\">\n                                                    SAMA\n                                                </span>\n                                            </template>\n                                        </td>\n                                        <td class=\"p-4 text-center\">\n                                            <button @click=\"hapusDraftItem(item.id)\" class=\"w-8 h-8 rounded-lg bg-rose-50 hover:bg-rose-100 text-rose-500 hover:text-rose-600 flex items-center justify-center transition-all\" title=\"Hapus\">\n                                                <i class=\"fa-solid fa-trash-can text-xs\"></i>\n                                            </button>\n                                        </td>\n                                    </tr>\n                                </template>\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n                <div class=\"h-10\"></div>\n            </div>\n        </main>\n    </div>\n\n    <!-- MODAL TAMBAH PRODUK -->\n    <div x-show=\"showModal\" class=\"fixed inset-0 z-50 flex items-center justify-center p-2 bg-slate-900/60 backdrop-blur-sm\" x-transition x-cloak>\n        <div class=\"bg-white rounded-[1.5rem] shadow-2xl border border-slate-100 w-full max-w-5xl max-h-[94vh] flex flex-col overflow-hidden\">\n            <div class=\"px-5 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50\">\n                <h3 class=\"text-sm font-black text-slate-800 flex items-center gap-2 tracking-wide uppercase\"><i class=\"fa-solid fa-basket-shopping text-primary\"></i> Tambah Bahan Baku</h3>\n                <div class=\"flex items-center gap-2\">\n                    <button @click=\"closeModal()\" class=\"px-4 py-2 rounded-xl font-bold text-xs text-slate-600 bg-white border border-slate-200 hover:bg-slate-100 transition-colors\">Batal</button>\n                    <button @click=\"tambahKeDraft()\" \n                            :disabled=\"opnameItems.filter(i=>i.checked).length === 0\"\n                            class=\"px-5 py-2 rounded-xl font-black text-xs text-white bg-emerald-500 hover:bg-emerald-600 shadow-sm transition-all flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed\">\n                        TAMBAH ( <span x-text=\"opnameItems.filter(i=>i.checked).length\"></span> )\n                    </button>\n                </div>\n            </div>\n\n            <div class=\"px-5 py-3 border-b border-slate-100 bg-white flex flex-wrap items-center gap-2\">\n                <!-- Store selector -->\n                <select x-model=\"selectedWarehouse\" @change=\"onModalWarehouseChange()\" class=\"bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-black text-slate-700 outline-none focus:border-primary cursor-pointer\">\n                    <?php\n                    try {\n                        if (!isset(\$pdo)) require_once '../../config/database.php';\n                        \$stmt_wh2 = \$pdo->query(\"SELECT id, name FROM warehouses ORDER BY id ASC\");\n                        \$wh_idx2 = 1;\n                        while (\$wh_row2 = \$stmt_wh2->fetch(PDO::FETCH_ASSOC)) {\n                            \$disp2 = preg_replace('/gudang\s*0?(\d+)/i', 'Store $1', \$wh_row2['name']);\n                            if (\$disp2 === \$wh_row2['name']) \$disp2 = 'Store ' . \$wh_idx2;\n                            echo '<option value=\"' . \$wh_row2['id'] . '\">' . htmlspecialchars(\$disp2) . '</option>';\n                            \$wh_idx2++;\n                        }\n                    } catch (Exception \$e) {}\n                    ?>\n                </select>\n                <!-- Kategori filter -->\n                <select x-model=\"modalCategoryFilter\" @change=\"loadAllProducts(true)\" class=\"bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-black text-slate-700 outline-none focus:border-primary cursor-pointer\">\n                    <option value=\"\">Semua Kategori</option>\n                    <template x-for=\"cat in modalCategories\" :key=\"cat\">\n                        <option :value=\"cat\" x-text=\"cat\"></option>\n                    </template>\n                </select>\n                <!-- Search -->\n                <div class=\"relative flex-1 min-w-[200px]\">\n                    <i class=\"fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs\"></i>\n                    <input type=\"text\" x-model=\"modalSearch\" @input.debounce.300ms=\"loadAllProducts(true)\" placeholder=\"Cari Bahan Baku / SKU / Kode...\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl pl-8 pr-4 py-2 text-xs font-bold text-slate-700 outline-none focus:border-primary\">\n                </div>\n            </div>\n\n            <div class=\"px-5 py-2 bg-blue-50 border-b border-blue-100 text-[10px] font-black text-blue-700 flex items-center gap-2 uppercase tracking-widest\">\n                <i class=\"fa-solid fa-circle-info\"></i> Maksimal 500 bahan baku terpilih tiap penambahan\n            </div>\n\n            <div class=\"flex-1 overflow-y-auto custom-scrollbar\">\n                <table class=\"w-full text-left border-collapse whitespace-nowrap\">\n                    <thead class=\"sticky top-0 z-10 bg-white border-b border-slate-200 shadow-sm\">\n                        <tr class=\"text-[11px] text-slate-500 uppercase tracking-widest\">\n                            <th class=\"p-3.5 w-10\"><input type=\"checkbox\" @change=\"toggleSelectAll(\$event)\" :checked=\"allOnPageChecked\" class=\"rounded cursor-pointer w-4 h-4 accent-emerald-500\"></th>\n                            <th class=\"p-3.5 font-black\">Bahan Baku</th>\n                            <th class=\"p-3.5 font-black\">Kode / SKU</th>\n                            <th class=\"p-3.5 font-black\">Gudang</th>\n                            <th class=\"p-3.5 font-black text-center\">Stok Sistem</th>\n                            <th class=\"p-3.5 font-black text-center text-primary\">Stok Aktual</th>\n                        </tr>\n                    </thead>\n                    <tbody class=\"text-sm divide-y divide-slate-100\">\n                        <tr x-show=\"isModalLoading\">\n                            <td colspan=\"6\" class=\"p-10 text-center text-slate-400 font-bold\">\n                                <i class=\"fa-solid fa-circle-notch fa-spin text-2xl text-primary mb-2 block\"></i>Memuat produk...\n                            </td>\n                        </tr>\n                        <tr x-show=\"!isModalLoading && modalProducts.length === 0\">\n                            <td colspan=\"6\" class=\"p-10 text-center text-slate-400\">\n                                <i class=\"fa-solid fa-search text-3xl text-slate-200 mb-2 block\"></i>Bahan baku tidak ditemukan.\n                            </td>\n                        </tr>\n                        <template x-for=\"prod in modalProducts\" :key=\"prod.id\">\n                            <tr class=\"hover:bg-slate-50 transition-colors border-b border-slate-50\"\n                                :class=\"getItemById(prod.id) && getItemById(prod.id).checked ? 'bg-slate-50' : ''\">\n                                <td class=\"p-3.5\">\n                                    <input type=\"checkbox\" \n                                           :checked=\"getItemById(prod.id) && getItemById(prod.id).checked\"\n                                           @change=\"toggleProductCheck(prod, \$event)\"\n                                           class=\"rounded cursor-pointer w-4 h-4 accent-emerald-500\">\n                                </td>\n                                <td class=\"p-3.5\">\n                                    <div class=\"font-black text-slate-800 text-sm\" x-text=\"prod.name\"></div>\n                                    <div class=\"text-[10px] text-slate-400 font-black tracking-widest uppercase mt-0.5\" x-text=\"prod.category || 'PRODUK'\"></div>\n                                </td>\n                                <td class=\"p-3.5 text-xs font-black text-slate-500\" x-text=\"prod.code || '-'\"></td>\n                                <td class=\"p-3.5 text-xs font-black text-slate-500\">\n                                    <span x-text=\"prod.warehouse_id == 2 ? 'Gudang 02' : 'gudang 01'\"></span>\n                                </td>\n                                <td class=\"p-3.5 text-center font-black text-slate-500 text-sm\" x-text=\"prod.stock\"></td>\n                                <td class=\"p-3.5 text-center\">\n                                    <div class=\"flex items-center justify-center gap-1\">\n                                        <button @click=\"ensureItem(prod); decrementStock(prod.id)\" \n                                                class=\"w-8 h-8 rounded-lg bg-white border border-slate-200 hover:bg-slate-100 text-slate-600 font-black text-lg flex items-center justify-center transition-all leading-none select-none\">−</button>\n                                        <input type=\"number\" \n                                               :value=\"getItemById(prod.id) ? getItemById(prod.id).actual_stock : 0\"\n                                               @focus=\"ensureItem(prod)\"\n                                               @change=\"ensureItem(prod); setActualStock(prod.id, \$event.target.value)\"\n                                               @click.stop\n                                               class=\"w-14 bg-white border border-slate-200 rounded-lg text-center font-black text-sm text-slate-800 outline-none py-1.5 focus:border-primary focus:ring-1 focus:ring-primary/20\"\n                                               min=\"0\">\n                                        <button @click=\"ensureItem(prod); incrementStock(prod.id)\" \n                                                class=\"w-8 h-8 rounded-lg bg-white border border-slate-200 hover:bg-slate-100 text-slate-600 font-black text-lg flex items-center justify-center transition-all leading-none select-none\">+</button>\n                                    </div>\n                                </td>\n                            </tr>\n                        </template>\n                    </tbody>\n                </table>\n            </div>\n\n            <div class=\"px-5 py-3 border-t border-slate-100 bg-white flex items-center justify-between gap-3\">\n                <span class=\"text-[10px] font-black text-slate-400 tracking-widest uppercase\">TOTAL: <span x-text=\"modalTotalProducts\"></span> BAHAN</span>\n                <div x-show=\"modalTotalPages > 1\" class=\"flex items-center gap-1 flex-wrap\">\n                    <button x-show=\"modalPage > 1\" @click=\"goToModalPage(modalPage - 1)\" class=\"w-8 h-8 rounded-lg bg-white border border-slate-200 text-slate-600 text-xs font-black hover:bg-slate-100\">&lsaquo;</button>\n                    <template x-for=\"p in modalPageRange\" :key=\"p\">\n                        <button @click=\"goToModalPage(p)\" class=\"w-8 h-8 rounded-lg text-xs font-black transition-all\" :class=\"p === modalPage ? 'bg-primary text-white border-primary' : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-100'\" x-text=\"p\"></button>\n                    </template>\n                    <button x-show=\"modalPage < modalTotalPages\" @click=\"goToModalPage(modalPage + 1)\" class=\"w-8 h-8 rounded-lg bg-white border border-slate-200 text-slate-600 text-xs font-black hover:bg-slate-100\">&rsaquo;</button>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <script>window.CURRENT_WAREHOUSE_ID = <?= !empty(\$_SESSION['pos_warehouse_id']) ? intval(\$_SESSION['pos_warehouse_id']) : 1 ?>;</script>\n    <script src=\"tambah.js?v=<?= time() ?>\"></script>\n</body>\n</html>";
$tambah_js = "document.addEventListener('alpine:init', () => {\n    Alpine.data('opnameTambahApp', () => ({\n        // Draft State\n        tanggal: new Date().toISOString().split('T')[0],\n        notes: '',\n        draftItems: [], // array of {id, name, category, system_stock, actual_stock, ...}\n        isPosting: false,\n\n        // Modal State\n        showModal: false,\n        selectedWarehouse: window.CURRENT_WAREHOUSE_ID || '1',\n        modalProducts: [],\n        modalPage: 1,\n        modalTotalPages: 1,\n        modalTotalProducts: 0,\n        modalSearch: '',\n        modalCategoryFilter: '',\n        modalCategories: [],\n        isModalLoading: false,\n        \n        // Items currently being checked in modal before adding to draft\n        opnameItems: [], \n\n        init() {\n            // Initialize anything if needed\n        },\n\n        // ---- Computed ----\n        get allOnPageChecked() {\n            if (!this.modalProducts.length) return false;\n            return this.modalProducts.every(p => {\n                const item = this.opnameItems.find(i => i.id == p.id);\n                return item && item.checked;\n            });\n        },\n\n        get modalPageRange() {\n            const total = this.modalTotalPages;\n            const cur = this.modalPage;\n            const pages = [];\n            const max = Math.min(total, 10);\n            let start = Math.max(1, cur - 4);\n            let end = Math.min(total, start + max - 1);\n            if (end - start < max - 1) start = Math.max(1, end - max + 1);\n            for (let i = start; i <= end; i++) pages.push(i);\n            return pages;\n        },\n\n        // ---- Modal Actions ----\n        async openModal() {\n            this.showModal = true;\n            this.modalPage = 1;\n            this.modalSearch = '';\n            this.modalCategoryFilter = '';\n            // Reset modal selection state to prepare for new selections\n            this.opnameItems = [];\n            \n            // Auto-populate opnameItems with draft items so they appear checked/with stock if already added\n            this.draftItems.forEach(d => {\n                this.opnameItems.push({...d, checked: true});\n            });\n            \n            await this.loadAllProducts();\n        },\n\n        closeModal() {\n            this.showModal = false;\n            this.modalProducts = [];\n            this.opnameItems = [];\n        },\n\n        onModalWarehouseChange() {\n            this.opnameItems = [];\n            this.modalCategoryFilter = '';\n            this.modalSearch = '';\n            this.modalCategories = [];\n            this.loadAllProducts(true);\n        },\n\n        async loadAllProducts(resetPage = false) {\n            if (resetPage) this.modalPage = 1;\n            this.isModalLoading = true;\n            try {\n                const url = `logic.php?action=get_all_products&warehouse_id=\${encodeURIComponent(this.selectedWarehouse)}&page=\${this.modalPage}&keyword=\${encodeURIComponent(this.modalSearch)}&category=\${encodeURIComponent(this.modalCategoryFilter)}`;\n                const res = await fetch(url);\n                const data = await res.json();\n                if (data.status === 'success') {\n                    this.modalProducts = data.data || [];\n                    this.modalTotalPages = parseInt(data.total_pages) || 1;\n                    this.modalTotalProducts = parseInt(data.total) || 0;\n                    if (data.categories && data.categories.length && !this.modalCategories.length) {\n                        this.modalCategories = data.categories;\n                    }\n                }\n            } catch(e) { console.error(e); }\n            finally { this.isModalLoading = false; }\n        },\n\n        async goToModalPage(p) {\n            if (p < 1 || p > this.modalTotalPages) return;\n            this.modalPage = p;\n            await this.loadAllProducts();\n        },\n\n        // ---- Checkbox & Counter Logic in Modal ----\n        getItemById(id) {\n            return this.opnameItems.find(i => i.id == id) || null;\n        },\n\n        ensureItem(prod) {\n            const existing = this.opnameItems.find(i => i.id == prod.id);\n            if (!existing) {\n                this.opnameItems.push({\n                    id: prod.id,\n                    code: prod.code,\n                    name: prod.name,\n                    category: prod.category || '-',\n                    system_stock: parseInt(prod.stock || 0),\n                    actual_stock: 0,\n                    price: parseFloat(prod.price || 0),\n                    checked: true\n                });\n            } else if (!existing.checked) {\n                existing.checked = true;\n            }\n        },\n\n        toggleProductCheck(prod, event) {\n            const checked = event.target.checked;\n            const existing = this.opnameItems.find(i => i.id == prod.id);\n            if (checked) {\n                if (!existing) {\n                    this.opnameItems.push({\n                        id: prod.id,\n                        code: prod.code,\n                        name: prod.name,\n                        category: prod.category || '-',\n                        system_stock: parseInt(prod.stock || 0),\n                        actual_stock: 0,\n                        price: parseFloat(prod.price || 0),\n                        checked: true\n                    });\n                } else {\n                    existing.checked = true;\n                }\n            } else {\n                if (existing) existing.checked = false;\n            }\n        },\n\n        toggleSelectAll(event) {\n            const checked = event.target.checked;\n            this.modalProducts.forEach(prod => {\n                const existing = this.opnameItems.find(i => i.id == prod.id);\n                if (checked) {\n                    if (!existing) {\n                        this.opnameItems.push({\n                            id: prod.id, code: prod.code, name: prod.name,\n                            category: prod.category || '-',\n                            system_stock: parseInt(prod.stock || 0),\n                            actual_stock: 0,\n                            price: parseFloat(prod.price || 0),\n                            checked: true\n                        });\n                    } else { existing.checked = true; }\n                } else {\n                    if (existing) existing.checked = false;\n                }\n            });\n        },\n\n        incrementStock(id) {\n            const item = this.getItemById(id);\n            if (item) item.actual_stock++;\n        },\n\n        decrementStock(id) {\n            const item = this.getItemById(id);\n            if (item && item.actual_stock > 0) item.actual_stock--;\n        },\n\n        setActualStock(id, val) {\n            const item = this.getItemById(id);\n            if (item) {\n                let v = parseInt(val);\n                if (isNaN(v) || v < 0) v = 0;\n                item.actual_stock = v;\n            }\n        },\n\n        // ---- Draft List Actions ----\n        tambahKeDraft() {\n            const checkedItems = this.opnameItems.filter(i => i.checked);\n            checkedItems.forEach(item => {\n                const existingIndex = this.draftItems.findIndex(d => d.id === item.id);\n                if (existingIndex > -1) {\n                    // Update existing\n                    this.draftItems[existingIndex].actual_stock = item.actual_stock;\n                } else {\n                    // Add new\n                    this.draftItems.push({...item});\n                }\n            });\n            this.closeModal();\n            if (typeof Swal !== 'undefined') {\n                Swal.fire({\n                    toast: true,\n                    position: 'top-end',\n                    icon: 'success',\n                    title: `\${checkedItems.length} produk diproses`,\n                    showConfirmButton: false,\n                    timer: 1500\n                });\n            }\n        },\n\n        hapusDraftItem(id) {\n            this.draftItems = this.draftItems.filter(i => i.id !== id);\n        },\n\n        incrementDraftStock(id) {\n            const item = this.draftItems.find(i => i.id === id);\n            if (item) item.actual_stock++;\n        },\n\n        decrementDraftStock(id) {\n            const item = this.draftItems.find(i => i.id === id);\n            if (item && item.actual_stock > 0) item.actual_stock--;\n        },\n\n        // ---- Posting ----\n        async postingOpname() {\n            if (this.draftItems.length === 0) return;\n            \n            if (typeof Swal === 'undefined') return;\n            const conf = await Swal.fire({\n                title: 'Posting Opname?',\n                text: `Anda akan menyimpan opname untuk \${this.draftItems.length} bahan baku.`,\n                icon: 'question',\n                showCancelButton: true,\n                confirmButtonColor: '#3b82f6',\n                confirmButtonText: 'Ya, Posting!',\n                cancelButtonText: 'Batal'\n            });\n\n            if (!conf.isConfirmed) return;\n\n            this.isPosting = true;\n            try {\n                // Ensure correct warehouse\n                let wId = parseInt(this.selectedWarehouse);\n                if (isNaN(wId) || wId <= 0) {\n                    wId = window.CURRENT_WAREHOUSE_ID || 1;\n                }\n\n                const payload = {\n                    items: this.draftItems.map(d => ({\n                        product_id: d.id,\n                        system_stock: d.system_stock,\n                        actual_stock: d.actual_stock\n                    })),\n                    notes: this.notes,\n                    tanggal: this.tanggal\n                };\n\n                const res = await fetch(`logic.php?action=save_opname_batch&warehouse_id=\${wId}`, {\n                    method: 'POST',\n                    headers: {\n                        'Content-Type': 'application/json'\n                    },\n                    body: JSON.stringify(payload)\n                });\n                \n                const data = await res.json();\n                if (data.status === 'success') {\n                    await Swal.fire({\n                        title: 'Berhasil!',\n                        text: data.message || 'Opname berhasil diposting.',\n                        icon: 'success',\n                        timer: 2000,\n                        showConfirmButton: false\n                    });\n                    window.location.href = 'index.php'; // Redirect back to history\n                } else {\n                    Swal.fire('Error', data.message || 'Gagal menyimpan batch opname.', 'error');\n                }\n            } catch (e) {\n                console.error(e);\n                Swal.fire('Error', 'Terjadi kesalahan sistem saat menyimpan batch.', 'error');\n            } finally {\n                this.isPosting = false;\n            }\n        }\n    }));\n});\n";
